from builtins import str, object
import datetime
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
logger = BackgroundLogger.Instance()


class Builder(object):

    # def __init__(self, ue_type, mobile_adb_id, bts_id, ue_ip, iperf_pc_ip,
    #              profile_params, **kwargs):
    def __init__(self, rat, ue_type, mobile_adb_id, bts_id, ue_ip, traffic_ip,
                 profile_name, ipv4_or_6, iperf_section, **kwargs):
        self._set_iperf_params(rat, ue_type, mobile_adb_id, bts_id, ue_ip,
                               traffic_ip, profile_name, ipv4_or_6,
                               iperf_section, **kwargs)

    def build_iperf_commands(self, alias):
        iperf_server_cmd, server_log = self._build_iperf_server_cmd(alias)
        iperf_client_cmd, client_log = self._build_iperf_client_cmd(alias)
        if self.direction.lower() == 'ul':
            return iperf_client_cmd, client_log, iperf_server_cmd, server_log
        elif self.direction.lower() == 'dl':
            return iperf_server_cmd, server_log, iperf_client_cmd, client_log

    def _build_iperf_server_cmd(self, alias):
        logger.debug('Building Iperf Server Cmd')
        iperf_server_cmd = ''
        log_file = self._get_log_file_name('server', alias)
        adb_prefix = self.adb_option if self.direction.lower() == 'dl' else ''
        logger.debug('Building Iperf Server Cmd')
        if self.ue_type == 'dongle' or self.ue_type == 'module':
            iperf_server_cmd =\
                '{adb_prefix}iperf -s {{bind}} {proto} {ipv6_option} -i1' \
                ' -p {port} > {log_file} 2>&1 & echo $!'.format(
                    adb_prefix=adb_prefix, proto=self.protocol_option,
                    ipv6_option=self.ipv6_option, port=self.iperf_port,
                    log_file=log_file)
        elif self.ue_type == 'mobile':
            iperf_server_cmd =\
                '{adb_prefix}iperf -s {proto} {ipv6_option} -i1 -p {port} >' \
                ' {log_file} 2>&1 & echo $!'.format(
                    adb_prefix=adb_prefix, proto=self.protocol_option,
                    ipv6_option=self.ipv6_option, port=self.iperf_port,
                    log_file=log_file)
        elif self.ue_type == 'iphy':
            iperf_server_cmd =\
                'iperf -s {proto} -i1 -p {port} {ipv6_option} > {log_file}' \
                ' 2>&1 & echo $!'.format(proto=self.protocol_option,
                                         ipv6_option=self.ipv6_option,
                                         port=self.iperf_port,
                                         log_file=log_file)
        elif self.ue_type == 'airphone':
            iperf_server_cmd =\
                'iperf -s {proto} -i1 -p {port} {ipv6_option} -B {{bind}} >' \
                ' {log_file} 2>&1 & echo $!'.format(
                    proto=self.protocol_option, ipv6_option=self.ipv6_option,
                    port=self.iperf_port, bind=self.server_bind_ip,
                    log_file=log_file)
        return iperf_server_cmd, log_file

    def _build_iperf_client_cmd(self, alias):
        iperf_client_cmd = ''
        adb_prefix = self.adb_option if self.direction.lower() == 'ul' else ''
        log_file = self._get_log_file_name('client', alias)
        if self.ue_type == 'dongle' or self.ue_type == 'module':
            iperf_client_cmd =\
                "{adb_prefix}iperf -c {server} {{bind}} {proto} " \
                "{ipv6_option} -i1 -l {len} -b {bw} -p {port} -t 86400 > " \
                "{log_file} 2>&1 & echo $!".format(
                    adb_prefix=adb_prefix, server=self.server_ip,
                    proto=self.protocol_option, ipv6_option=self.ipv6_option,
                    len=self.packet_len, bw=self.bandwidth,
                    port=self.iperf_port, log_file=log_file)
        elif self.ue_type == 'mobile':
            iperf_client_cmd =\
                "{adb_prefix}iperf -c {server} {proto} {ipv6_option} -i1" \
                " -l {len} -b {bw} -p {port} -t 86400 > {log_file} 2>&1 &" \
                " echo $!".format(adb_prefix=adb_prefix, server=self.server_ip,
                                  proto=self.protocol_option,
                                  ipv6_option=self.ipv6_option,
                                  len=self.packet_len,
                                  bw=self.bandwidth, port=self.iperf_port,
                                  log_file=log_file)
        elif self.ue_type == 'iphy':
            iperf_client_cmd =\
                "iperf -c {server} {proto} {ipv6_option} -i1 -l {len} -b" \
                " {bw} -p {port} -t 86400 >{log_file} 2>&1 &echo $!".format(
                    server=self.server_ip, proto=self.protocol_option,
                    ipv6_option=self.ipv6_option, len=self.packet_len,
                    bw=self.bandwidth, port=self.iperf_port,
                    log_file=log_file)
        elif self.ue_type == 'airphone':
            iperf_client_cmd =\
                "iperf -c {server} {proto} {ipv6_option} -i1 -l {len} -b" \
                " {bw} -p {port} -t 86400 >{log_file} 2>&1 &echo $!".format(
                    server=self.server_ip, proto=self.protocol_option,
                    ipv6_option=self.ipv6_option, len=self.packet_len,
                    bw=self.bandwidth, port=self.iperf_port,
                    log_file=log_file)

        return iperf_client_cmd, log_file

    def _build_command_options(self):
        adb_option = ''
        # if self.ue_type.lower() == 'mobile':
        if self.mobile_adb_id != '':
            if self.android_version > 410:
                if self.android_version >= 900:
                    adb_option = './'
                else:
                    adb_option = 'adb -s {} shell su -c /data/data/com.magic' \
                                 'androidapps.iperf/bin/'.format(self.mobile_adb_id)
            else:
                adb_option = 'adb -s {} shell /data/data/com.magicandroid' \
                             'apps.iperf/bin/'.format(self.mobile_adb_id)
        return adb_option

    def _get_iperf_protocol_option(self):
        protocol_option = ''
        if self.protocol.lower() == 'udp':
            protocol_option = '-u'
        return protocol_option

    def _get_iperf_server_ip(self):
        server_ip = ''
        if self.direction.lower() == 'ul':
            server_ip = self.traffic_ip
        elif self.direction.lower() == 'dl':
            server_ip = self.ue_ip
        logger.debug("iperf server IP :: {0}\niperf traffic IP :: {1}\n".format(server_ip, self.traffic_ip))
        return server_ip

    def _get_log_file_name(self, mode, alias):
        return 'iperf_{}_{}_{}_{}_{}_{}_{}_{}.txt'.format(
            self.rat, self.mobile_adb_id, alias, self.bts_id, self.protocol,
            self.direction, mode, str(datetime.datetime.now().strftime(
                "%Y%m%d%I%M%S%p")))

    # def _set_iperf_params(self, ue_type, mobile_adb_id, bts_id, ue_ip,
    #                       iperf_pc_ip, profile_params, **kwargs):
    def _set_iperf_params(self, rat, ue_type, mobile_adb_id, bts_id, ue_ip,
                          traffic_ip, profile_name, ipv4_or_6, iperf_section,
                          **kwargs):
        self.rat = rat
        self.ue_type = ue_type
        self.mobile_adb_id = mobile_adb_id
        self.bts_id = bts_id
        self.ue_ip = ue_ip
        self.traffic_ip = traffic_ip
        self.protocol = get_config_variable(['traffic_profiles', profile_name,
                                             'protocol'])
        # profile_params['protocol']
        self.direction = get_config_variable(['traffic_profiles', profile_name,
                                              'direction']).lower()
        # profile_params['direction']
        self.packet_len = get_config_variable(['traffic_profiles',
                                               profile_name, 'packet_len'])
        # profile_params['packet_len']
        self.bandwidth = get_config_variable(['traffic_profiles', profile_name,
                                              'bandwidth'])
        # profile_params['bandwidth']
        self.iperf_port = get_config_variable(['traffic_profiles',
                                               profile_name, 'port'])
        # profile_params['port']
        self.server_bind_ip = get_config_variable(['iperf', iperf_section,
                                                   'server_bind_ip'])
        # self.iperf_port = self.bts_id
        # self.iperf_port = '63247'
        self.protocol_option = self._get_iperf_protocol_option()
        self.server_ip = self._get_iperf_server_ip()
        if self.mobile_adb_id != '':
            self.android_version = kwargs['version']
        self.adb_option = self._build_command_options()
        self.ipv6_option = '-V' if ipv4_or_6.lower().strip() == 'ipv6' else ''
